-- Forum catalogue version (#34, ADR 0014):
--   * catalogue_meta: global (GLOBAL_TABLES), no RLS. One row per seeded system catalogue; the
--     owner-role seed (`seedForumCatalogue`, run by `pnpm db:migrate`) records the version of the
--     catalogue data it applied under key `forum_catalogue`.
--   * The app and clerk roles may read it, never write it; only the owner seeds catalogues.
-- A new table only: nothing existing is altered or dropped.
CREATE TABLE "catalogue_meta" (
	"key" text PRIMARY KEY NOT NULL,
	"version" text NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
